  /// 取字符串的第一个有效首字母：拉丁字母直接大写，汉字取拼音首字母，
  /// 数字与其他符号归入 `#`。
  static String of(String text) {
    for (final rune in text.runes) {
      final initial = _ofRune(rune);
      if (initial != null) return initial;
    }
    return '#';
  }

  static String? _ofRune(int rune) {
    if (rune >= 0x61 && rune <= 0x7A) return String.fromCharCode(rune - 32);
    if (rune >= 0x41 && rune <= 0x5A) return String.fromCharCode(rune);
    if (rune >= 0x30 && rune <= 0x39) return '#';
    if (rune >= _start && rune <= _end) {
      final letter = _table[rune - _start];
      return letter == '#' ? null : letter;
    }
    return null;
  }
